/* @autogenerated */
package net.civeira.phylax.feature.observe.ingest;

import java.util.Optional;

import org.eclipse.microprofile.config.inject.ConfigProperty;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.observe.source.SourceRegistry;
import net.civeira.phylax.feature.observe.source.SourceRegistry.Source;

/**
 * Decides if a request to the OTLP endpoints is accepted, from the X-Observe-Key header and the
 * Origin header of the browsers.
 *
 * <ul>
 * <li>With key: the source of the key must accept events and, if the call comes from a browser, its
 * origin must be in allowed-origins.</li>
 * <li>Without key: rejected with {@code app.observe.ingest.require-key=true}; otherwise accepted,
 * and each event is attributed by its service.name to a source that accepts events (or
 * dropped).</li>
 * </ul>
 */
@ApplicationScoped
@RequiredArgsConstructor
public class IngestGuard {

  public static final String KEY_HEADER = "X-Observe-Key";

  /**
   * @param status 0 if accepted, the HTTP status otherwise
   * @param source source of the key, empty without key
   */
  public record Decision(int status, Optional<Source> source) {
    public boolean accepted() {
      return 0 == status;
    }
  }

  private final SourceRegistry registry;
  private final @ConfigProperty(name = "app.observe.ingest.require-key",
      defaultValue = "false") boolean requireKey;

  public Decision check(final String key, final String origin) {
    if (null == key || key.isBlank()) {
      return requireKey ? new Decision(401, Optional.empty()) : new Decision(0, Optional.empty());
    }
    Optional<Source> source = registry.byKey(key.trim());
    if (source.isEmpty()) {
      return new Decision(401, Optional.empty());
    }
    if (!source.get().accepting()) {
      return new Decision(403, source);
    }
    if (null != origin && !origin.isBlank() && !source.get().allowedOrigins().isEmpty()
        && !source.get().allowedOrigins().contains(origin)) {
      return new Decision(403, source);
    }
    return new Decision(0, source);
  }

  public static boolean isIngestPath(final String path) {
    String normalized = path.startsWith("/") ? path : "/" + path;
    return normalized.startsWith("/v1/traces") || normalized.startsWith("/v1/logs");
  }
}
